import path from "node:path";

const root = process.cwd();
const files = {"lib/companies.ts": "import { getAllResearch, type ResearchItem } from \"@/lib/research\";\n\nexport type CompanyProfile = {\n  slug: string;\n  ticker: string;\n  name: string;\n  sector: string;\n  summary: string;\n};\n\nexport type CompanyDirectoryItem = CompanyProfile & {\n  reports: ResearchItem[];\n  latest?: ResearchItem;\n};\n\nexport const COMPANY_PROFILES: CompanyProfile[] = [\n  {\n    slug: \"aradel\",\n    ticker: \"ARADEL\",\n    name: \"Aradel Holdings\",\n    sector: \"Energy\",\n    summary: \"Scale and cash have arrived. The remaining question is how much survives finance costs, tax, capex and minority interests for ordinary shareholders.\",\n  },\n  {\n    slug: \"champion-breweries\",\n    ticker: \"CHAMPION\",\n    name: \"Champion Breweries\",\n    sector: \"Consumer goods\",\n    summary: \"Revenue has grown sharply, while debt, dilution and finance costs remain central to the shareholder case.\",\n  },\n  {\n    slug: \"dangote-refinery\",\n    ticker: \"DANGREF\",\n    name: \"Dangote Refinery\",\n    sector: \"Energy\",\n    summary: \"A major industrial asset whose minority value depends on debt, uptime, governance and the price eventually paid.\",\n  },\n  {\n    slug: \"first-holdco\",\n    ticker: \"FIRSTHOLDCO\",\n    name: \"First HoldCo\",\n    sector: \"Banking\",\n    summary: \"A cleaner bank after recapitalisation, with the legacy loan book and ownership reshuffle still part of the thesis.\",\n  },\n  {\n    slug: \"gtco\",\n    ticker: \"GTCO\",\n    name: \"Guaranty Trust Holding Company\",\n    sector: \"Banking\",\n    summary: \"Cheap deposits, formidable capital and rare institutional restraint. The remaining argument is price.\",\n  },\n  {\n    slug: \"honeywell-flour\",\n    ticker: \"HONYFLOUR\",\n    name: \"Honeywell Flour Mills\",\n    sector: \"Consumer goods\",\n    summary: \"Demand is dependable. The shareholder economics still need kneading.\",\n  },\n  {\n    slug: \"mtn-nigeria\",\n    ticker: \"MTNN\",\n    name: \"MTN Nigeria\",\n    sector: \"Telecommunications\",\n    summary: \"Data demand and a repaired balance sheet support the case. Energy costs and capex decide how much growth reaches shareholders.\",\n  },\n  {\n    slug: \"presco\",\n    ticker: \"PRESCO\",\n    name: \"Presco\",\n    sector: \"Agriculture\",\n    summary: \"An integrated palm-oil franchise with strong cash generation. The remaining argument is whether the price already knows.\",\n  },\n  {\n    slug: \"pz-nigeria\",\n    ticker: \"PZ\",\n    name: \"PZ Cussons Nigeria\",\n    sector: \"Consumer goods\",\n    summary: \"The rebound is real enough to underwrite. Sustainability, valuation and the parent-listing structure still matter.\",\n  },\n  {\n    slug: \"seplat-energy\",\n    ticker: \"SEPLAT\",\n    name: \"Seplat Energy\",\n    sector: \"Energy\",\n    summary: \"Dollar earnings, additional scale and lower leverage improve the franchise. Valuation and capital allocation still matter.\",\n  },\n  {\n    slug: \"stanbic-ibtc\",\n    ticker: \"STANBIC\",\n    name: \"Stanbic IBTC\",\n    sector: \"Banking\",\n    summary: \"Quality is evident. Quality still needs a price.\",\n  },\n  {\n    slug: \"tantalizers\",\n    ticker: \"TANTALIZER\",\n    name: \"Tantalizers\",\n    sector: \"Hospitality\",\n    summary: \"The restaurants are recovering, while the market is already paying for a wider diversification story.\",\n  },\n  {\n    slug: \"uba\",\n    ticker: \"UBA\",\n    name: \"United Bank for Africa\",\n    sector: \"Banking\",\n    summary: \"A formidable deposit franchise and continental reach, offset by asset-quality, cost and capital-efficiency questions.\",\n  },\n  {\n    slug: \"universal-insurance\",\n    ticker: \"UNIVINSURE\",\n    name: \"Universal Insurance\",\n    sector: \"Insurance\",\n    summary: \"Regulatory risk, governance discipline and the quality of the operating franchise sit at the centre of the case.\",\n  },\n  {\n    slug: \"vfd-group\",\n    ticker: \"VFDGROUP\",\n    name: \"VFD Group\",\n    sector: \"Financials\",\n    summary: \"Profit has recovered. Per-share compounding, financing drag and the moat still need proving.\",\n  },\n];\n\nexport function getCompanyDirectory(): CompanyDirectoryItem[] {\n  const research = getAllResearch();\n  return COMPANY_PROFILES\n    .map((profile) => {\n      const reports = research.filter((item) => item.ticker === profile.ticker);\n      return { ...profile, reports, latest: reports[0] };\n    })\n    .filter((item) => item.reports.length > 0);\n}\n\nexport function getCompanyBySlug(slug: string) {\n  return getCompanyDirectory().find((company) => company.slug === slug);\n}\n\nexport function getFeaturedCompanies(tickers: string[]) {\n  const wanted = new Map(tickers.map((ticker, index) => [ticker, index]));\n  return getCompanyDirectory()\n    .filter((company) => wanted.has(company.ticker))\n    .sort((a, b) => (wanted.get(a.ticker) ?? 99) - (wanted.get(b.ticker) ?? 99));\n}\n", "app/companies/page.tsx": "import type { Metadata } from \"next\";\nimport { formatDate } from \"@/components/BriefingCard\";\nimport { getCompanyDirectory } from \"@/lib/companies\";\n\nexport const metadata: Metadata = {\n  title: \"Company Directory\",\n  description: \"Seven Gates Research company coverage, organised by issuer and latest published view.\",\n  alternates: { canonical: \"/companies\" },\n  openGraph: {\n    title: \"Company Directory | Seven Gates Research\",\n    description: \"Follow the company. Test the thesis. Published coverage with the latest Seven Gates view in each company file.\",\n    url: \"/companies\",\n    type: \"website\",\n    images: [\"/opengraph-image\"],\n  },\n  twitter: {\n    card: \"summary_large_image\",\n    title: \"Company Directory | Seven Gates Research\",\n    description: \"Follow the company. Test the thesis.\",\n    images: [\"/opengraph-image\"],\n  },\n};\n\nexport default function CompaniesPage() {\n  const companies = getCompanyDirectory();\n\n  return <section className=\"archive\">\n    <div className=\"shell\">\n      <div className=\"archive-head\">\n        <p className=\"kicker\">THE COVERAGE DIRECTORY</p>\n        <h1>Follow the company. Test the thesis.</h1>\n        <p className=\"deck\">Published company coverage, organised around the latest research file. Prices and valuation ranges inside reports are dated snapshots, never live quotes.</p>\n      </div>\n\n      <div className=\"company-grid\">\n        {companies.map((company) => <article className=\"company-card\" key={company.slug}>\n          <div className=\"company-card-head\">\n            <span>{company.sector}</span>\n            <strong>{company.ticker}</strong>\n          </div>\n          <h2><a href={`/companies/${company.slug}`}>{company.name}</a></h2>\n          <p>{company.summary}</p>\n          {company.latest && <div className=\"company-latest\">\n            <span>Latest research</span>\n            <strong>{company.latest.title}</strong>\n            <small>{formatDate(company.latest.date)} · {company.latest.readingTime}</small>\n          </div>}\n          <a className=\"company-link\" href={`/companies/${company.slug}`}>Open company file →</a>\n        </article>)}\n      </div>\n    </div>\n  </section>;\n}\n", "app/companies/[slug]/page.tsx": "import type { Metadata } from \"next\";\nimport { notFound } from \"next/navigation\";\nimport { formatDate } from \"@/components/BriefingCard\";\nimport { getCompanyBySlug, getCompanyDirectory } from \"@/lib/companies\";\n\nexport function generateStaticParams() {\n  return getCompanyDirectory().map((company) => ({ slug: company.slug }));\n}\n\nexport async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {\n  const { slug } = await params;\n  const company = getCompanyBySlug(slug);\n  if (!company) return {};\n\n  return {\n    title: `${company.name} Research`,\n    description: company.summary,\n    alternates: { canonical: `/companies/${company.slug}` },\n    openGraph: {\n      title: `${company.name} | Seven Gates Research`,\n      description: company.summary,\n      url: `/companies/${company.slug}`,\n      type: \"website\",\n      images: [company.latest?.hero || \"/opengraph-image\"],\n    },\n    twitter: {\n      card: \"summary_large_image\",\n      title: `${company.name} | Seven Gates Research`,\n      description: company.summary,\n      images: [company.latest?.hero || \"/opengraph-image\"],\n    },\n  };\n}\n\nexport default async function CompanyPage({ params }: { params: Promise<{ slug: string }> }) {\n  const { slug } = await params;\n  const company = getCompanyBySlug(slug);\n  if (!company) notFound();\n\n  return <section className=\"archive\">\n    <div className=\"shell\">\n      <div className=\"company-file-head\">\n        <p className=\"kicker\">NGX / COMPANY COVERAGE · {company.ticker} · {company.sector}</p>\n        <h1>{company.name}</h1>\n        <p className=\"deck\">{company.summary}</p>\n        <div className=\"company-file-actions\">\n          {company.latest && <a className=\"button-link\" href={`/research/${company.latest.slug}`}>Read latest report →</a>}\n          <a className=\"button-link secondary\" href=\"/valuation-lab\">Open Valuation Lab →</a>\n        </div>\n      </div>\n\n      {company.latest && <section className=\"company-latest-panel\">\n        <p className=\"kicker\">LATEST PUBLISHED VIEW</p>\n        <h2>{company.latest.title}</h2>\n        <p>{company.latest.excerpt}</p>\n        <div className=\"meta\">\n          <span>{formatDate(company.latest.date)}</span>\n          <span>{company.latest.readingTime} read</span>\n          <span>{company.latest.researchType}</span>\n        </div>\n      </section>}\n\n      <section className=\"section compact-section\">\n        <div className=\"section-heading\">\n          <h2>Research filed under {company.ticker}</h2>\n          <a href=\"/research\">Search all research →</a>\n        </div>\n        <div className=\"archive-list\">\n          {company.reports.map((item) => <article className=\"archive-row\" key={item.slug}>\n            <time>{formatDate(item.date)}</time>\n            <div>\n              <h2>{item.title}</h2>\n              <p>{item.excerpt}</p>\n            </div>\n            <a href={`/research/${item.slug}`}>Read →</a>\n          </article>)}\n        </div>\n      </section>\n\n      <div className=\"disclaimer\"><strong>Company-file note.</strong> This page organises published Seven Gates research. It is not a live market-data feed and does not create a new recommendation. Use the date, assumptions and disclosures in the underlying report.</div>\n    </div>\n  </section>;\n}\n", "components/ValuationLab.tsx": "\"use client\";\n\nimport { useMemo, useState } from \"react\";\n\ntype ModelInput = {\n  currency: \"NGN\" | \"USD\" | \"GBP\" | \"EUR\";\n  revenue: number;\n  growth: number;\n  margin: number;\n  tax: number;\n  da: number;\n  capex: number;\n  workingCapital: number;\n  wacc: number;\n  terminalGrowth: number;\n  netDebt: number;\n  shares: number;\n  referencePrice: number;\n};\n\ntype NumericKey = Exclude<keyof ModelInput, \"currency\">;\ntype ForecastRow = {\n  year: number;\n  revenue: number;\n  ebit: number;\n  tax: number;\n  da: number;\n  capex: number;\n  workingCapital: number;\n  fcff: number;\n  pv: number;\n};\n\nconst DEFAULT_MODEL: ModelInput = {\n  currency: \"NGN\",\n  revenue: 1000,\n  growth: 10,\n  margin: 25,\n  tax: 30,\n  da: 4,\n  capex: 7,\n  workingCapital: 15,\n  wacc: 18,\n  terminalGrowth: 3,\n  netDebt: 100,\n  shares: 100,\n  referencePrice: 12,\n};\n\nconst symbols = { NGN: \"₦\", USD: \"$\", GBP: \"£\", EUR: \"€\" };\n\nfunction fmt(value: number, digits = 1) {\n  if (!Number.isFinite(value)) return \"n.m.\";\n  return new Intl.NumberFormat(\"en-GB\", { maximumFractionDigits: digits, minimumFractionDigits: 0 }).format(value);\n}\n\nfunction money(value: number, currency: ModelInput[\"currency\"], digits = 2) {\n  if (!Number.isFinite(value)) return \"n.m.\";\n  return `${symbols[currency]}${fmt(value, digits)}`;\n}\n\nfunction calculate(model: ModelInput, overrides: Partial<ModelInput> = {}) {\n  const input = { ...model, ...overrides };\n  const g = input.growth / 100;\n  const margin = input.margin / 100;\n  const taxRate = input.tax / 100;\n  const daRate = input.da / 100;\n  const capexRate = input.capex / 100;\n  const wcRate = input.workingCapital / 100;\n  const wacc = input.wacc / 100;\n  const terminalGrowth = input.terminalGrowth / 100;\n\n  if (input.shares <= 0 || wacc <= terminalGrowth || wacc <= 0) return null;\n\n  const rows: ForecastRow[] = [];\n  let previousRevenue = input.revenue;\n  let pvExplicit = 0;\n  let finalFcff = 0;\n\n  for (let year = 1; year <= 5; year += 1) {\n    const revenue = previousRevenue * (1 + g);\n    const ebit = revenue * margin;\n    const cashTax = Math.max(ebit, 0) * taxRate;\n    const da = revenue * daRate;\n    const capex = revenue * capexRate;\n    const workingCapital = (revenue - previousRevenue) * wcRate;\n    const fcff = ebit - cashTax + da - capex - workingCapital;\n    const pv = fcff / Math.pow(1 + wacc, year);\n    rows.push({ year, revenue, ebit, tax: cashTax, da, capex, workingCapital, fcff, pv });\n    pvExplicit += pv;\n    previousRevenue = revenue;\n    finalFcff = fcff;\n  }\n\n  const terminalValue = finalFcff * (1 + terminalGrowth) / (wacc - terminalGrowth);\n  const pvTerminal = terminalValue / Math.pow(1 + wacc, 5);\n  const enterpriseValue = pvExplicit + pvTerminal;\n  const equityValue = enterpriseValue - input.netDebt;\n  const valuePerShare = equityValue / input.shares;\n  const upside = input.referencePrice > 0 ? valuePerShare / input.referencePrice - 1 : NaN;\n  const marginOfSafety = valuePerShare > 0 ? 1 - input.referencePrice / valuePerShare : NaN;\n  const terminalShare = enterpriseValue !== 0 ? pvTerminal / enterpriseValue : NaN;\n\n  return { input, rows, enterpriseValue, equityValue, valuePerShare, upside, marginOfSafety, terminalShare };\n}\n\nfunction NumericInput({\n  label,\n  value,\n  onChange,\n  step = 1,\n  help,\n}: {\n  label: string;\n  value: number;\n  onChange: (value: number) => void;\n  step?: number;\n  help?: string;\n}) {\n  return <label className=\"lab-field\">\n    <span>{label}</span>\n    <input type=\"number\" value={value} step={step} onChange={(e) => onChange(Number(e.target.value))} />\n    {help && <small>{help}</small>}\n  </label>;\n}\n\nexport function ValuationLab() {\n  const [model, setModel] = useState<ModelInput>(DEFAULT_MODEL);\n  const [bear, setBear] = useState({ growth: 6, margin: 20, wacc: 18 });\n  const [bull, setBull] = useState({ growth: 14, margin: 28, wacc: 16 });\n  const [fairValue, setFairValue] = useState(15);\n  const [mosPrice, setMosPrice] = useState(12);\n  const [haircut, setHaircut] = useState(10);\n\n  const base = useMemo(() => calculate(model), [model]);\n  const bearValue = useMemo(() => calculate(model, bear), [model, bear]);\n  const bullValue = useMemo(() => calculate(model, bull), [model, bull]);\n\n  const update = (key: NumericKey, value: number) => setModel((current) => ({ ...current, [key]: value }));\n\n  const sensitivityWacc = [Math.max(model.terminalGrowth + 1.5, model.wacc - 2), model.wacc, model.wacc + 2];\n  const sensitivityGrowth = [Math.max(0, model.terminalGrowth - 1), model.terminalGrowth, model.terminalGrowth + 1];\n\n  const adjustedFairValue = fairValue * (1 - haircut / 100);\n  const mos = adjustedFairValue > 0 ? 1 - mosPrice / adjustedFairValue : NaN;\n\n  function downloadAssumptions() {\n    if (!base) return;\n    const payload = {\n      generatedAt: new Date().toISOString(),\n      note: \"Seven Gates Valuation Lab assumptions. Illustrative model, not a company forecast.\",\n      assumptions: model,\n      output: {\n        enterpriseValue: base.enterpriseValue,\n        equityValue: base.equityValue,\n        valuePerShare: base.valuePerShare,\n      },\n      forecast: base.rows,\n    };\n    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: \"application/json\" });\n    const url = URL.createObjectURL(blob);\n    const anchor = document.createElement(\"a\");\n    anchor.href = url;\n    anchor.download = \"seven-gates-valuation-assumptions.json\";\n    anchor.click();\n    URL.revokeObjectURL(url);\n  }\n\n  return <div className=\"lab-shell\">\n    <nav className=\"lab-jump\" aria-label=\"Valuation Lab sections\">\n      <a href=\"#dcf\">01 · DCF model</a>\n      <a href=\"#scenarios\">02 · Scenarios</a>\n      <a href=\"#margin-of-safety\">03 · Margin of safety</a>\n    </nav>\n\n    <div className=\"lab-note\">Illustrative models, not company forecasts. Use a dated report and your own assumptions. This unlevered cash-flow model is for operating businesses, not bank valuation. Inputs stay in your browser and are not uploaded to an account.</div>\n\n    <section className=\"lab-section\" id=\"dcf\">\n      <div className=\"lab-section-head\">\n        <div>\n          <p className=\"kicker\">01 · DISCOUNTED CASH FLOW</p>\n          <h2>Build the cash-flow case.</h2>\n        </div>\n        <button className=\"lab-button secondary\" type=\"button\" onClick={() => setModel(DEFAULT_MODEL)}>Reset example</button>\n      </div>\n\n      <div className=\"lab-layout\">\n        <div className=\"lab-panel\">\n          <label className=\"lab-field\">\n            <span>Model currency</span>\n            <select value={model.currency} onChange={(e) => setModel((current) => ({ ...current, currency: e.target.value as ModelInput[\"currency\"] }))}>\n              <option value=\"NGN\">NGN</option>\n              <option value=\"USD\">USD</option>\n              <option value=\"GBP\">GBP</option>\n              <option value=\"EUR\">EUR</option>\n            </select>\n            <small>Changes the unit label, not the input numbers.</small>\n          </label>\n          <div className=\"lab-input-grid\">\n            <NumericInput label=\"Starting revenue (millions)\" value={model.revenue} onChange={(v) => update(\"revenue\", v)} help=\"Last full year; use one currency throughout.\" />\n            <NumericInput label=\"Annual revenue growth (%)\" value={model.growth} onChange={(v) => update(\"growth\", v)} step={0.5} />\n            <NumericInput label=\"EBIT margin (%)\" value={model.margin} onChange={(v) => update(\"margin\", v)} step={0.5} />\n            <NumericInput label=\"Cash tax rate (%)\" value={model.tax} onChange={(v) => update(\"tax\", v)} step={0.5} />\n            <NumericInput label=\"D&A / revenue (%)\" value={model.da} onChange={(v) => update(\"da\", v)} step={0.5} />\n            <NumericInput label=\"Capex / revenue (%)\" value={model.capex} onChange={(v) => update(\"capex\", v)} step={0.5} />\n            <NumericInput label=\"Working capital / new revenue (%)\" value={model.workingCapital} onChange={(v) => update(\"workingCapital\", v)} step={0.5} />\n            <NumericInput label=\"Discount rate / WACC (%)\" value={model.wacc} onChange={(v) => update(\"wacc\", v)} step={0.5} help=\"Must exceed terminal growth.\" />\n            <NumericInput label=\"Terminal growth (%)\" value={model.terminalGrowth} onChange={(v) => update(\"terminalGrowth\", v)} step={0.5} />\n            <NumericInput label=\"Net debt (millions)\" value={model.netDebt} onChange={(v) => update(\"netDebt\", v)} help=\"Debt less cash. Negative means net cash.\" />\n            <NumericInput label=\"Diluted shares (millions)\" value={model.shares} onChange={(v) => update(\"shares\", v)} help=\"Match diluted shares to the equity claim.\" />\n            <NumericInput label=\"Reference price per share\" value={model.referencePrice} onChange={(v) => update(\"referencePrice\", v)} step={0.1} help=\"Your dated input; no live feed.\" />\n          </div>\n        </div>\n\n        <div className=\"lab-output\">\n          <p className=\"kicker\">YOUR ASSUMPTIONS IMPLY</p>\n          {base ? <>\n            <div className=\"lab-big-value\">{money(base.valuePerShare, model.currency)}</div>\n            <p className={base.upside >= 0 ? \"positive\" : \"negative\"}>{fmt(base.upside * 100, 1)}% versus your reference price</p>\n            <div className=\"lab-stat-grid\">\n              <div><span>Enterprise value (m)</span><strong>{fmt(base.enterpriseValue, 1)}</strong></div>\n              <div><span>Net debt (m)</span><strong>{fmt(model.netDebt, 1)}</strong></div>\n              <div><span>Equity value (m)</span><strong>{fmt(base.equityValue, 1)}</strong></div>\n              <div><span>Terminal value / EV</span><strong>{fmt(base.terminalShare * 100, 1)}%</strong></div>\n              <div><span>Margin of safety</span><strong>{fmt(base.marginOfSafety * 100, 1)}%</strong></div>\n            </div>\n            <button className=\"lab-button\" type=\"button\" onClick={downloadAssumptions}>Download assumptions & forecast</button>\n            <p className=\"lab-fine\">No automatic buy signal. The output is only as defensible as the inputs.</p>\n          </> : <div className=\"lab-error\">WACC must exceed terminal growth and diluted shares must be greater than zero.</div>}\n        </div>\n      </div>\n\n      {base && <>\n        <div className=\"lab-table-wrap\">\n          <table className=\"lab-table\">\n            <caption>Five-year operating forecast · {model.currency} millions</caption>\n            <thead><tr><th>Year</th><th>Revenue</th><th>EBIT</th><th>Cash tax</th><th>D&A</th><th>Capex</th><th>Δ working capital</th><th>FCFF</th><th>Present value</th></tr></thead>\n            <tbody>{base.rows.map((row) => <tr key={row.year}>\n              <td>{row.year}</td><td>{fmt(row.revenue, 1)}</td><td>{fmt(row.ebit, 1)}</td><td>{fmt(row.tax, 1)}</td><td>{fmt(row.da, 1)}</td><td>{fmt(row.capex, 1)}</td><td>{fmt(row.workingCapital, 1)}</td><td>{fmt(row.fcff, 1)}</td><td>{fmt(row.pv, 1)}</td>\n            </tr>)}</tbody>\n          </table>\n        </div>\n\n        <div className=\"lab-method\">\n          <h3>Calculation method & limits</h3>\n          <p>FCFF = EBIT - cash tax + D&A - capex - change in working capital. Each annual cash flow is discounted at WACC. Terminal value = year-five FCFF × (1 + terminal growth) ÷ (WACC - terminal growth), discounted five years. Equity value = enterprise value - net debt. Divide by diluted shares for value per share.</p>\n          <p>Constant ratios, year-end discounting and a perpetuity terminal value simplify reality. This model excludes minorities, pensions, associates, tax losses and separate lease adjustments. Adjust net debt and cash flows consistently before interpreting it.</p>\n        </div>\n\n        <div className=\"lab-table-wrap\">\n          <table className=\"lab-table compact\">\n            <caption>Sensitivity · per-share value · discount rate versus terminal growth</caption>\n            <thead><tr><th>WACC / terminal growth</th>{sensitivityGrowth.map((g) => <th key={g}>{fmt(g, 1)}%</th>)}</tr></thead>\n            <tbody>{sensitivityWacc.map((w) => <tr key={w}>\n              <th>{fmt(w, 1)}%</th>\n              {sensitivityGrowth.map((g) => {\n                const result = calculate(model, { wacc: w, terminalGrowth: g });\n                return <td key={g}>{result ? money(result.valuePerShare, model.currency) : \"n.m.\"}</td>;\n              })}\n            </tr>)}</tbody>\n          </table>\n        </div>\n      </>}\n    </section>\n\n    <section className=\"lab-section\" id=\"scenarios\">\n      <p className=\"kicker\">02 · SCENARIO COMPARISON</p>\n      <h2>Give the counterargument a number.</h2>\n      <p className=\"deck lab-deck\">Bear and bull override revenue growth, EBIT margin and discount rate. Every other assumption follows the DCF above. Labels describe cases, not guaranteed outcomes.</p>\n\n      <div className=\"scenario-grid\">\n        <div className=\"scenario-card\">\n          <span>Bear</span>\n          <NumericInput label=\"Revenue growth (%)\" value={bear.growth} onChange={(v) => setBear((x) => ({ ...x, growth: v }))} step={0.5} />\n          <NumericInput label=\"EBIT margin (%)\" value={bear.margin} onChange={(v) => setBear((x) => ({ ...x, margin: v }))} step={0.5} />\n          <NumericInput label=\"Discount rate (%)\" value={bear.wacc} onChange={(v) => setBear((x) => ({ ...x, wacc: v }))} step={0.5} />\n          <strong>{bearValue ? money(bearValue.valuePerShare, model.currency) : \"n.m.\"}</strong>\n          <small>Value per share</small>\n        </div>\n\n        <div className=\"scenario-card base\">\n          <span>Base</span>\n          <p>Uses all inputs from the DCF above.</p>\n          <strong>{base ? money(base.valuePerShare, model.currency) : \"n.m.\"}</strong>\n          <small>Value per share</small>\n        </div>\n\n        <div className=\"scenario-card\">\n          <span>Bull</span>\n          <NumericInput label=\"Revenue growth (%)\" value={bull.growth} onChange={(v) => setBull((x) => ({ ...x, growth: v }))} step={0.5} />\n          <NumericInput label=\"EBIT margin (%)\" value={bull.margin} onChange={(v) => setBull((x) => ({ ...x, margin: v }))} step={0.5} />\n          <NumericInput label=\"Discount rate (%)\" value={bull.wacc} onChange={(v) => setBull((x) => ({ ...x, wacc: v }))} step={0.5} />\n          <strong>{bullValue ? money(bullValue.valuePerShare, model.currency) : \"n.m.\"}</strong>\n          <small>Value per share</small>\n        </div>\n      </div>\n    </section>\n\n    <section className=\"lab-section\" id=\"margin-of-safety\">\n      <p className=\"kicker\">03 · MARGIN OF SAFETY</p>\n      <h2>Leave room to be wrong.</h2>\n      <div className=\"lab-layout\">\n        <div className=\"lab-panel\">\n          <div className=\"lab-input-grid\">\n            <NumericInput label={`Fair value per share (${model.currency})`} value={fairValue} onChange={setFairValue} step={0.1} />\n            <NumericInput label={`Reference price (${model.currency})`} value={mosPrice} onChange={setMosPrice} step={0.1} />\n            <NumericInput label=\"Your risk haircut (%)\" value={haircut} onChange={setHaircut} step={0.5} help=\"A discretionary reduction to fair value, not a calibrated probability.\" />\n          </div>\n        </div>\n        <div className=\"lab-output\">\n          <p className=\"kicker\">MARGIN OF SAFETY AFTER YOUR HAIRCUT</p>\n          <div className=\"lab-big-value\">{fmt(mos * 100, 1)}%</div>\n          <p>Adjusted fair value: <strong>{money(adjustedFairValue, model.currency)}</strong></p>\n          <p className={mos >= 0 ? \"positive\" : \"negative\"}>{mos >= 0 ? \"Price is below your adjusted value.\" : \"Price is above your adjusted value.\"}</p>\n          <p className=\"lab-fine\">Margin of safety = 1 - price ÷ adjusted fair value. It differs from potential upside, which divides by price. Neither is an instruction to trade.</p>\n        </div>\n      </div>\n    </section>\n  </div>;\n}\n", "app/valuation-lab/page.tsx": "import type { Metadata } from \"next\";\nimport { ValuationLab } from \"@/components/ValuationLab\";\n\nexport const metadata: Metadata = {\n  title: \"NGX Valuation Lab\",\n  description: \"Make the assumptions explicit. Build a DCF, compare bear/base/bull scenarios and test a margin of safety.\",\n  alternates: { canonical: \"/valuation-lab\" },\n  openGraph: {\n    title: \"NGX Valuation Lab | Seven Gates Research\",\n    description: \"Price is observable. Value is an argument. Make the assumptions explicit, then see how much room they leave.\",\n    url: \"/valuation-lab\",\n    type: \"website\",\n    images: [\"/opengraph-image\"],\n  },\n  twitter: {\n    card: \"summary_large_image\",\n    title: \"NGX Valuation Lab | Seven Gates Research\",\n    description: \"Price is observable. Value is an argument.\",\n    images: [\"/opengraph-image\"],\n  },\n};\n\nexport default function ValuationLabPage() {\n  return <section className=\"archive\">\n    <div className=\"shell\">\n      <div className=\"archive-head valuation-head\">\n        <p className=\"kicker\">NGX VALUATION LAB · TOOLS & ASSUMPTIONS</p>\n        <h1>What has to go right?</h1>\n        <p className=\"deck\">Price is observable. Value is an argument. Make the assumptions explicit, then see how much room they leave.</p>\n      </div>\n      <ValuationLab />\n    </div>\n  </section>;\n}\n", "app/opengraph-image.tsx": "import { ImageResponse } from \"next/og\";\n\nexport const alt = \"Seven Gates Research. Independent research on companies, markets and power.\";\nexport const size = { width: 1200, height: 630 };\nexport const contentType = \"image/png\";\n\nexport default function OpenGraphImage() {\n  return new ImageResponse(\n    <div style={{\n      width: \"100%\",\n      height: \"100%\",\n      display: \"flex\",\n      flexDirection: \"column\",\n      justifyContent: \"space-between\",\n      background: \"#1A1F24\",\n      color: \"#FBF8F1\",\n      padding: \"72px 82px\",\n      borderTop: \"16px solid #A67C3D\",\n      fontFamily: \"Georgia, serif\",\n    }}>\n      <div style={{ display: \"flex\", alignItems: \"center\", gap: 28 }}>\n        <div style={{\n          width: 86,\n          height: 104,\n          display: \"flex\",\n          alignItems: \"center\",\n          justifyContent: \"center\",\n          border: \"3px solid #C69A52\",\n          borderRadius: \"44px 44px 8px 8px\",\n          color: \"#C69A52\",\n          fontSize: 38,\n        }}>Ⅶ</div>\n        <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n          <div style={{ color: \"#C69A52\", fontSize: 25, letterSpacing: 5 }}>SEVEN GATES RESEARCH</div>\n          <div style={{ color: \"#C6BFAE\", fontSize: 22 }}>Knowledge. Context. Advantage.</div>\n        </div>\n      </div>\n\n      <div style={{ display: \"flex\", flexDirection: \"column\", gap: 24 }}>\n        <div style={{ fontSize: 68, lineHeight: 1.02, maxWidth: 920 }}>Independent research on companies, markets and power.</div>\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 22, fontSize: 24, color: \"#C6BFAE\" }}>\n          <span>Nigeria at the centre.</span>\n          <span style={{ color: \"#A67C3D\" }}>•</span>\n          <span>The world in view.</span>\n        </div>\n      </div>\n    </div>,\n    size,\n  );\n}\n", "app/icon.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\">\n  <rect width=\"64\" height=\"64\" rx=\"12\" fill=\"#1A1F24\"/>\n  <path d=\"M18 50V28C18 16 24 9 32 9s14 7 14 19v22\" fill=\"none\" stroke=\"#C69A52\" stroke-width=\"3\"/>\n  <path d=\"M24 24h16M24 32h16\" stroke=\"#A67C3D\" stroke-width=\"2\"/>\n  <text x=\"32\" y=\"45\" text-anchor=\"middle\" font-size=\"18\" font-family=\"Georgia,serif\" fill=\"#FBF8F1\">VII</text>\n</svg>\n", "app/manifest.ts": "import type { MetadataRoute } from \"next\";\n\nexport default function manifest(): MetadataRoute.Manifest {\n  return {\n    name: \"Seven Gates Research\",\n    short_name: \"Seven Gates\",\n    description: \"Independent research on companies, markets and power.\",\n    start_url: \"/\",\n    display: \"standalone\",\n    background_color: \"#FBF8F1\",\n    theme_color: \"#1A1F24\",\n    icons: [\n      {\n        src: \"/icon.svg\",\n        sizes: \"any\",\n        type: \"image/svg+xml\",\n      },\n    ],\n  };\n}\n", "app/layout.tsx": "import type { Metadata } from \"next\";\nimport { Archivo, Cinzel, EB_Garamond } from \"next/font/google\";\nimport \"./globals.css\";\n\nconst cinzel = Cinzel({ subsets: [\"latin\"], weight: [\"600\"], variable: \"--font-display\" });\nconst garamond = EB_Garamond({ subsets: [\"latin\"], weight: [\"400\",\"500\",\"600\"], variable: \"--font-editorial\" });\nconst archivo = Archivo({ subsets: [\"latin\"], weight: [\"400\",\"500\",\"600\"], variable: \"--font-interface\" });\n\nexport const metadata: Metadata = {\n  metadataBase: new URL(\"https://sevengatesresearch.com\"),\n  title: { default: \"Seven Gates Research\", template: \"%s | Seven Gates Research\" },\n  description: \"Independent research on companies, markets and power.\",\n  applicationName: \"Seven Gates Research\",\n  authors: [{ name: \"Seven Gates Research\" }],\n  creator: \"Seven Gates Research\",\n  publisher: \"Seven Gates Research\",\n  manifest: \"/manifest.webmanifest\",\n  icons: { icon: \"/icon.svg\" },\n  openGraph: {\n    title: \"Seven Gates Research\",\n    description: \"Independent research on companies, markets and power.\",\n    url: \"/\",\n    siteName: \"Seven Gates Research\",\n    locale: \"en_GB\",\n    type: \"website\",\n    images: [{ url: \"/opengraph-image\", width: 1200, height: 630, alt: \"Seven Gates Research\" }],\n  },\n  twitter: {\n    card: \"summary_large_image\",\n    title: \"Seven Gates Research\",\n    description: \"Independent research on companies, markets and power.\",\n    images: [\"/opengraph-image\"],\n  },\n};\n\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"en\" className={`${cinzel.variable} ${garamond.variable} ${archivo.variable}`}>\n      <body>\n        <header className=\"site-header\">\n          <div className=\"shell header-inner\">\n            <a className=\"brand\" href=\"/\">\n              <span className=\"gate-mark\" aria-hidden=\"true\">Ⅶ</span>\n              <span><strong>SEVEN GATES RESEARCH</strong><small>Knowledge. Context. Advantage.</small></span>\n            </a>\n            <nav aria-label=\"Primary navigation\">\n              <a href=\"/briefing\">Daily Brief</a>\n              <a href=\"/briefing/archive\">Archive</a>\n              <a href=\"/research\">Research</a>\n              <a href=\"/companies\">Company directory</a>\n              <a href=\"/valuation-lab\">Valuation Lab</a>\n              <a href=\"/about\">About</a>\n            </nav>\n          </div>\n        </header>\n        <main>{children}</main>\n        <footer className=\"site-footer\">\n          <div className=\"shell footer-inner\">\n            <div><strong>SEVEN GATES RESEARCH</strong><p>Independent research on companies, markets and power.</p></div>\n            <div className=\"footer-links\" aria-label=\"Footer navigation\">\n              <a href=\"/briefing\">Daily Brief</a>\n              <a href=\"/research\">Research</a>\n              <a href=\"/companies\">Company directory</a>\n              <a href=\"/valuation-lab\">Valuation Lab</a>\n              <a href=\"/about\">About</a>\n            </div>\n            <p className=\"house-rule\">Interesting first. Correct always.</p>\n          </div>\n        </footer>\n      </body>\n    </html>\n  );\n}\n", "app/page.tsx": "import type { Metadata } from \"next\";\nimport { BriefingCard, formatDate } from \"@/components/BriefingCard\";\nimport { getAllBriefings } from \"@/lib/content\";\nimport { getFeaturedCompanies } from \"@/lib/companies\";\nimport { getAllResearch } from \"@/lib/research\";\n\nexport const metadata: Metadata = {\n  title: { absolute: \"Seven Gates Research | Daily Briefs, Company Research & Valuation\" },\n  description: \"Independent equity and macro research. Nigeria at the centre, the world in view. Daily Briefs, company research and the NGX Valuation Lab.\",\n  alternates: { canonical: \"/\" },\n  openGraph: {\n    title: \"Seven Gates Research | Daily Briefs, Company Research & Valuation\",\n    description: \"Independent equity and macro research. Nigeria at the centre, the world in view.\",\n    url: \"/\",\n    type: \"website\",\n    images: [\"/opengraph-image\"],\n  },\n  twitter: {\n    card: \"summary_large_image\",\n    title: \"Seven Gates Research | Daily Briefs, Company Research & Valuation\",\n    description: \"Independent equity and macro research. Nigeria at the centre, the world in view.\",\n    images: [\"/opengraph-image\"],\n  },\n};\n\nexport default function HomePage() {\n  const briefings = getAllBriefings();\n  const latest = briefings[0];\n  const recent = briefings.slice(1, 4);\n  const research = getAllResearch().slice(0, 3);\n  const companies = getFeaturedCompanies([\"SEPLAT\", \"GTCO\", \"VFDGROUP\", \"UBA\", \"MTNN\"]);\n\n  return <>\n    <section className=\"hero\"><div className=\"shell hero-grid\">\n      <div>\n        <p className=\"kicker\">SEVEN GATES RESEARCH</p>\n        <h1>Independent research on companies, markets and power.</h1>\n        <p className=\"deck\">Nigerian in knowledge, international in scope, sceptical by habit. The argument comes first. The arithmetic gets the final vote.</p>\n      </div>\n      <aside className=\"hero-card\">\n        <p className=\"kicker\">LATEST DAILY BRIEF</p>\n        {latest ? <><h2>{latest.title}</h2><p>{formatDate(latest.date)} · {latest.readingTime}</p><p>{latest.excerpt}</p><a href={`/briefing/${latest.date}`}>Read today’s brief →</a></>\n        : <><h2>Migration in progress</h2><p>The publication engine is live in source control.</p><a href=\"/briefing/archive\">Open archive →</a></>}\n      </aside>\n    </div></section>\n\n    <section className=\"section\"><div className=\"shell\">\n      <div className=\"section-heading\"><h2>Latest research</h2><a href=\"/research\">Explore all research →</a></div>\n      {research.length ? <div className=\"cards\">{research.map((item) => <article className=\"card\" key={item.slug}>\n        <time>{formatDate(item.date)} · {item.researchType}</time>\n        <h3>{item.title}</h3>\n        <p>{item.excerpt}</p>\n        <a href={`/research/${item.slug}`}>Read the analysis →</a>\n      </article>)}</div> : <div className=\"empty-state\">Research migration is in progress.</div>}\n    </div></section>\n\n    <section className=\"section coverage-section\"><div className=\"shell\">\n      <div className=\"section-heading\"><div><p className=\"kicker\">THE COVERAGE DIRECTORY</p><h2>Follow the company. Test the thesis.</h2></div><a href=\"/companies\">All companies →</a></div>\n      <p className=\"section-intro\">Published coverage, with the latest view in each company file. Values inside reports are dated research snapshots, never live quotes.</p>\n      <div className=\"company-strip\">\n        {companies.map((company) => <article className=\"company-mini\" key={company.slug}>\n          <span>{company.sector}</span>\n          <strong>{company.ticker}</strong>\n          <h3>{company.name}</h3>\n          <p>{company.summary}</p>\n          {company.latest && <small>Research as of {formatDate(company.latest.date)}</small>}\n          <a href={`/companies/${company.slug}`}>Open company file →</a>\n        </article>)}\n      </div>\n    </div></section>\n\n    <section className=\"section valuation-home\"><div className=\"shell hero-grid\">\n      <div>\n        <p className=\"kicker\">THE NGX VALUATION LAB</p>\n        <h2>Bring your own assumptions.</h2>\n        <p className=\"deck\">What has to go right for the price to make sense? Change the inputs and see what happens to value.</p>\n        <a className=\"button-link\" href=\"/valuation-lab\">Open the Valuation Lab →</a>\n      </div>\n      <div className=\"valuation-steps\">\n        <div><strong>01</strong><span>Discounted cash flow</span><p>Growth, reinvestment and the cost of capital.</p></div>\n        <div><strong>02</strong><span>Bear, base & bull</span><p>Compare the cases behind your conviction.</p></div>\n        <div><strong>03</strong><span>Margin of safety</span><p>How much room is there to be wrong?</p></div>\n      </div>\n    </div></section>\n\n    <section className=\"section\"><div className=\"shell\">\n      <div className=\"section-heading\"><h2>Recent briefings</h2><a href=\"/briefing/archive\">View archive →</a></div>\n      {recent.length ? <div className=\"cards\">{recent.map((item) => <BriefingCard key={item.date} item={item}/>)}</div>\n      : <div className=\"empty-state\">The briefing archive populates automatically from <code>content/briefings</code>.</div>}\n    </div></section>\n\n    <section className=\"section\" style={{ background: \"var(--parchment)\" }}><div className=\"shell hero-grid\">\n      <div>\n        <p className=\"kicker\">THE SEVEN GATES</p>\n        <h2>Judgement before ornament.</h2>\n        <p className=\"deck\">Ownership and governance. Business economics. Financial integrity. Capital allocation. Competitive endurance. Valuation and expected return. Downside, catalysts and portfolio fit.</p>\n      </div>\n      <div className=\"hero-card\"><h3>House rule</h3><p>Interesting first. Correct always.</p><p>Strong opinions, loosely held. Capital, tightly held.</p></div>\n    </div></section>\n  </>;\n}\n", "app/research/page.tsx": "import type { Metadata } from \"next\";\nimport { ResearchLibrary } from \"@/components/ResearchLibrary\";\nimport { getAllResearch } from \"@/lib/research\";\n\nexport const metadata: Metadata = {\n  title: \"Research Library\",\n  description: \"Company underwrites, market notes and essays from Seven Gates Research.\",\n  alternates: { canonical: \"/research\" },\n  openGraph: {\n    title: \"Research Library | Seven Gates Research\",\n    description: \"Company underwrites, market notes and essays from Seven Gates Research.\",\n    url: \"/research\",\n    type: \"website\",\n    images: [\"/opengraph-image\"],\n  },\n  twitter: {\n    card: \"summary_large_image\",\n    title: \"Research Library | Seven Gates Research\",\n    description: \"Company underwrites, market notes and essays from Seven Gates Research.\",\n    images: [\"/opengraph-image\"],\n  },\n};\n\nexport default function ResearchPage() {\n  const items = getAllResearch().map(({ html, hero, heroAlt, heroCaption, legacyUrl, legacyImported, draft, kicker, ...item }) => item);\n  return <section className=\"archive\">\n    <div className=\"shell\">\n      <div className=\"archive-head\">\n        <p className=\"kicker\">RESEARCH · REPORTS · NOTES · ESSAYS</p>\n        <h1>Arguments sorted by the work they do.</h1>\n        <p className=\"deck\">Reports underwrite companies. Notes update an argument. Essays examine markets, institutions and power. Geography is a filter, not a separate corridor.</p>\n      </div>\n      <ResearchLibrary items={items} />\n    </div>\n  </section>;\n}\n", "app/briefing/archive/page.tsx": "import type { Metadata } from \"next\";\nimport { formatDate } from \"@/components/BriefingCard\";\nimport { getAllBriefings } from \"@/lib/content\";\n\nexport const metadata: Metadata = {\n  title: \"Daily Brief Archive\",\n  description: \"Permanent dated editions of the Seven Gates Research Daily Brief, newest first.\",\n  alternates: { canonical: \"/briefing/archive\" },\n  openGraph: {\n    title: \"Daily Brief Archive | Seven Gates Research\",\n    description: \"Permanent dated editions of the Seven Gates Research Daily Brief, newest first.\",\n    url: \"/briefing/archive\",\n    type: \"website\",\n    images: [\"/opengraph-image\"],\n  },\n  twitter: {\n    card: \"summary_large_image\",\n    title: \"Daily Brief Archive | Seven Gates Research\",\n    description: \"Permanent dated editions of the Seven Gates Research Daily Brief, newest first.\",\n    images: [\"/opengraph-image\"],\n  },\n};\n\nexport default function ArchivePage() {\n  const items = getAllBriefings();\n  return <section className=\"archive\"><div className=\"shell\">\n    <div className=\"archive-head\"><p className=\"kicker\">DAILY BRIEF ARCHIVE</p><h1>Every morning kept.</h1><p className=\"deck\">Permanent dated editions, newest first. Yesterday does not disappear because today has opinions.</p></div>\n    {items.length ? <div className=\"archive-list\">{items.map(item => <article className=\"archive-row\" key={item.date}><time>{formatDate(item.date)}</time><div><h2>{item.title}</h2><p>{item.excerpt}</p></div><a href={`/briefing/${item.date}`}>Read →</a></article>)}</div>\n    : <div className=\"empty-state\">No migrated editions yet. Add a validated Markdown file to <code>content/briefings/YYYY-MM-DD.md</code>.</div>}\n  </div></section>;\n}\n", "app/about/page.tsx": "import type { Metadata } from \"next\";\n\nexport const metadata: Metadata = {\n  title: \"About & Standards\",\n  description: \"The editorial and analytical principles behind Seven Gates Research.\",\n  alternates: { canonical: \"/about\" },\n  openGraph: {\n    title: \"About & Standards | Seven Gates Research\",\n    description: \"The editorial and analytical principles behind Seven Gates Research.\",\n    url: \"/about\",\n    type: \"website\",\n    images: [\"/opengraph-image\"],\n  },\n  twitter: {\n    card: \"summary_large_image\",\n    title: \"About & Standards | Seven Gates Research\",\n    description: \"The editorial and analytical principles behind Seven Gates Research.\",\n    images: [\"/opengraph-image\"],\n  },\n};\n\nexport default function AboutPage(){\n  return <section className=\"archive\"><div className=\"shell\">\n    <div className=\"archive-head\">\n      <p className=\"kicker\">ABOUT & STANDARDS</p>\n      <h1>Seven Gates Research</h1>\n      <p className=\"deck\">Independent research on companies, markets and power. Nigerian in knowledge rather than costume, internationally intelligible, sceptical of cant and willing to change its mind when the evidence changes.</p>\n    </div>\n    <div className=\"method-grid\">\n      <div><strong>01</strong><h2>Ownership & governance</h2><p>Who controls the asset, who gets paid first, and whether minority shareholders have meaningful protection.</p></div>\n      <div><strong>02</strong><h2>Business economics</h2><p>Returns on capital, pricing power, reinvestment needs and the actual cash engine underneath the story.</p></div>\n      <div><strong>03</strong><h2>Financial integrity</h2><p>Cash conversion, leverage, accounting quality and the small footnotes that occasionally contain the larger truth.</p></div>\n      <div><strong>04</strong><h2>Capital allocation</h2><p>Whether management compounds, dilutes, overpays or simply mistakes activity for value creation.</p></div>\n      <div><strong>05</strong><h2>Competitive endurance</h2><p>How long the economics can survive competition, regulation, technology and the occasional macro ambush.</p></div>\n      <div><strong>06</strong><h2>Valuation & return</h2><p>A good company can still be a poor purchase. Price is always part of the argument.</p></div>\n      <div><strong>07</strong><h2>Downside & catalysts</h2><p>What breaks the thesis, what changes the odds, and what evidence would force us to change our mind.</p></div>\n    </div>\n  </div></section>;\n}\n", "app/research/[slug]/page.tsx": "import type { Metadata } from \"next\";\nimport { notFound } from \"next/navigation\";\nimport { formatDate } from \"@/components/BriefingCard\";\nimport { getAllResearch, getRelatedResearch, getResearchItem } from \"@/lib/research\";\n\nexport function generateStaticParams() {\n  return getAllResearch().map((x) => ({ slug: x.slug }));\n}\n\nexport async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {\n  const { slug } = await params;\n  const item = getResearchItem(slug);\n  if (!item) return {};\n  const image = item.hero || \"/opengraph-image\";\n  return {\n    title: item.title,\n    description: item.excerpt,\n    alternates: { canonical: `/research/${item.slug}` },\n    openGraph: {\n      title: item.title,\n      description: item.excerpt,\n      url: `/research/${item.slug}`,\n      type: \"article\",\n      publishedTime: item.date,\n      images: [image],\n    },\n    twitter: {\n      card: \"summary_large_image\",\n      title: item.title,\n      description: item.excerpt,\n      images: [image],\n    },\n  };\n}\n\nexport default async function ResearchArticlePage({ params }: { params: Promise<{ slug: string }> }) {\n  const { slug } = await params;\n  const item = getResearchItem(slug);\n  if (!item) notFound();\n  const related = getRelatedResearch(slug, 6);\n\n  return <article className=\"article-shell\">\n    <header className=\"article-head\">\n      <p className=\"kicker\">{item.kicker}</p>\n      <h1>{item.title}</h1>\n      <p className=\"deck\">{item.excerpt}</p>\n      <div className=\"meta\">\n        <span>{formatDate(item.date)}</span>\n        <span>{item.readingTime} read</span>\n        <span>{item.researchType}</span>\n        <span>{item.category}</span>\n        {item.ticker && <span>{item.ticker}</span>}\n      </div>\n    </header>\n\n    {item.hero && <figure className=\"article-hero\">\n      <img src={item.hero} alt={item.heroAlt || item.title} />\n      {item.heroCaption && <figcaption>{item.heroCaption}</figcaption>}\n    </figure>}\n\n    <div className=\"article-grid\">\n      <div>\n        <div className=\"prose research-prose\" dangerouslySetInnerHTML={{ __html: item.html }} />\n        <div className=\"disclaimer\"><strong>Disclaimer.</strong> Seven Gates Research is provided for informational and educational purposes only. It is not personal investment, legal, tax or financial advice. Prices, assumptions and valuations are dated research snapshots. Readers should verify the evidence and consider their own circumstances before making investment decisions.</div>\n      </div>\n      <aside className=\"aside\">\n        <div className=\"aside-box\">\n          <h3>Related research</h3>\n          {related.length ? <ul className=\"aside-list\">{related.map((x) => <li key={x.slug}>\n            <time>{formatDate(x.date)}</time>\n            <a href={`/research/${x.slug}`}>{x.title}</a>\n          </li>)}</ul> : <p>No related migrated research yet.</p>}\n          <p><a href=\"/research\">Browse full research archive →</a></p>\n        </div>\n        <div className=\"aside-box\">\n          <h3>Seven Gates rule</h3>\n          <p>Interesting first. Correct always.</p>\n        </div>\n      </aside>\n    </div>\n  </article>;\n}\n", "app/briefing/[date]/page.tsx": "import type { Metadata } from \"next\";\nimport { notFound } from \"next/navigation\";\nimport { formatDate } from \"@/components/BriefingCard\";\nimport { getAllBriefings, getBriefing, getEarlierBriefings } from \"@/lib/content\";\n\nexport function generateStaticParams() { return getAllBriefings().map(x => ({date:x.date})); }\n\nexport async function generateMetadata({params}:{params:Promise<{date:string}>}):Promise<Metadata>{\n  const {date}=await params; const item=getBriefing(date); if(!item)return {};\n  const image=item.hero||\"/opengraph-image\";\n  return {\n    title:item.title,\n    description:item.excerpt,\n    alternates:{canonical:`/briefing/${item.date}`},\n    openGraph:{title:item.title,description:item.excerpt,url:`/briefing/${item.date}`,type:\"article\",publishedTime:item.date,images:[image]},\n    twitter:{card:\"summary_large_image\",title:item.title,description:item.excerpt,images:[image]}\n  };\n}\n\nexport default async function BriefingPage({params}:{params:Promise<{date:string}>}){\n  const {date}=await params; const item=getBriefing(date); if(!item)notFound(); const earlier=getEarlierBriefings(date,7);\n  return <article className=\"article-shell\">\n    <header className=\"article-head\"><p className=\"kicker\">{item.kicker}</p><h1>{item.title}</h1><p className=\"deck\">{item.excerpt}</p><div className=\"meta\"><span>{formatDate(item.date)}</span><span>{item.readingTime} read</span><span>Seven Gates Research</span></div></header>\n    {item.hero && <figure className=\"article-hero\"><img src={item.hero} alt={item.heroAlt||\"Seven Gates editorial illustration\"}/><figcaption>{item.heroCaption||\"Editorial illustration.\"}</figcaption></figure>}\n    <div className=\"article-grid\"><div><div className=\"prose\" dangerouslySetInnerHTML={{__html:item.html}}/>\n      <div className=\"disclaimer\"><strong>Disclaimer.</strong> This publication is provided for informational and educational purposes only. It does not constitute financial, investment, tax, legal, or other professional advice, nor does it constitute a recommendation, offer, solicitation, or invitation to buy, sell, or hold any security, financial instrument, or investment. The analysis may contain opinions, estimates, assumptions, forecasts and forward-looking statements based on information considered reliable at the time of publication. Such views may change without notice, and actual outcomes may differ materially. Investing involves risk, including the possible loss of principal. Readers should conduct their own independent research, verify the information presented, consider their individual circumstances and risk tolerance, and obtain advice from appropriately qualified professional advisers before making any investment decision. Seven Gates Research accepts no responsibility for investment decisions made solely on the basis of this publication.</div>\n    </div><aside className=\"aside\"><div className=\"aside-box\"><h3>Earlier Briefings</h3>{earlier.length?<ul className=\"aside-list\">{earlier.map(x=><li key={x.date}><time>{formatDate(x.date)}</time><a href={`/briefing/${x.date}`}>{x.title}</a></li>)}</ul>:<p>No earlier migrated editions.</p>}<p><a href=\"/briefing/archive\">View full archive →</a></p></div><div className=\"aside-box\"><h3>Seven Gates rule</h3><p>Interesting first. Correct always.</p></div></aside></div>\n  </article>;\n}\n", "app/sitemap.ts": "import type { MetadataRoute } from \"next\";\nimport { getAllBriefings } from \"@/lib/content\";\nimport { getCompanyDirectory } from \"@/lib/companies\";\nimport { getAllResearch } from \"@/lib/research\";\n\nexport default function sitemap(): MetadataRoute.Sitemap {\n  const base = \"https://sevengatesresearch.com\";\n\n  const staticRoutes = [\"\", \"/briefing/archive\", \"/research\", \"/companies\", \"/valuation-lab\", \"/about\"]\n    .map((route) => ({ url: `${base}${route}` }));\n\n  const briefs = getAllBriefings().map((item) => ({\n    url: `${base}/briefing/${item.date}`,\n    lastModified: new Date(`${item.date}T12:00:00Z`),\n  }));\n\n  const research = getAllResearch().map((item) => ({\n    url: `${base}/research/${item.slug}`,\n    lastModified: new Date(`${item.date}T12:00:00Z`),\n  }));\n\n  const companies = getCompanyDirectory().map((company) => ({\n    url: `${base}/companies/${company.slug}`,\n    lastModified: company.latest ? new Date(`${company.latest.date}T12:00:00Z`) : undefined,\n  }));\n\n  return [...staticRoutes, ...briefs, ...research, ...companies];\n}\n"};
