for (const [relative, content] of Object.entries(files)) {
  const target = path.join(root, relative);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content, "utf8");
  console.log(`Patched ${relative}`);
}

const cssPath = path.join(root, "app", "globals.css");
let currentCss = fs.readFileSync(cssPath, "utf8");
const start = "/* PRELAUNCH_PATCH_START */";
const end = "/* PRELAUNCH_PATCH_END */";
const escapedStart = start.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const escapedEnd = end.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const pattern = new RegExp(`${escapedStart}[\\s\\S]*?${escapedEnd}\\n?`);
if (currentCss.includes(start) && currentCss.includes(end)) {
  currentCss = currentCss.replace(pattern, cssBlock.trim() + "\n");
} else {
  currentCss = currentCss.trimEnd() + "\n\n" + cssBlock.trim() + "\n";
}
fs.writeFileSync(cssPath, currentCss, "utf8");

const checks = [
  ["app/research/page.tsx", 'title: "Research Library"'],
  ["app/page.tsx", 'alternates: { canonical: "/" }'],
  ["app/sitemap.ts", '"/valuation-lab"'],
  ["app/sitemap.ts", '"/companies"'],
  ["app/layout.tsx", 'href="/valuation-lab"'],
  ["app/layout.tsx", 'href="/companies"'],
  ["components/ValuationLab.tsx", "FCFF = EBIT - cash tax"],
];

for (const [relative, needle] of checks) {
  const text = fs.readFileSync(path.join(root, relative), "utf8");
  if (!text.includes(needle)) throw new Error(`Pre-launch check failed: ${relative} missing ${needle}`);
}

const sitemapText = fs.readFileSync(path.join(root, "app", "sitemap.ts"), "utf8");
if (sitemapText.includes('"", "/briefing",')) throw new Error("Sitemap still contains redirect route /briefing");

console.log("Seven Gates pre-launch patch applied.");
